financial_db.analytics.customer_360.customer_type\\",\\"tags\\":[],\\"constraint\\":\\"NULL\\",\\"children\\":[]},{\\"name\\":\\"segment\\",\\"dataType\\":\\"VARCHAR\\",\\"dataLength\\":40,\\"dataTypeDisplay\\":\\"character varying(40)\\",\\"fullyQualifiedName\\":\\"financial_postgres.financial_db.analytics.customer_360.segment\\",\\"tags\\":[],\\"constraint\\":\\"NULL\\",\\"children\\":[]},{\\"name\\":\\"industry\\",\\"dataType\\":\\"VARCHAR\\",\\"dataLength\\":100,\\"dataTypeDisplay\\":\\"character varying(100)\\",\\"fullyQualifiedName\\":\\"financial_postgres.financial_db.analytics.customer_360.industry\\",\\"tags\\":[],\\"constraint\\":\\"NULL\\",\\"children\\":[]},{\\"name\\":\\"country\\",\\"dataType\\":\\"VARCHAR\\",\\"dataLength\\":100,\\"dataTypeDisplay\\":\\"character varying(100)\\",\\"fullyQualifiedName\\":\\"financial_postgres.financial_db.analytics.customer_360.country\\",\\"tags\\":[],\\"constraint\\":\\"NULL\\",\\"children\\":[]},{\\"name\\":\\"customer_status\\",\\"dataType\\":\\"VARCHAR\\",\\"dataLength\\":30,\\"dataTypeDisplay\\":\\"character varying(30)\\",\\"fullyQualifiedName\\":\\"financial_postgres.financial_db.analytics.customer_360.customer_status\\",\\"tags\\":[],\\"constraint\\":\\"NULL\\",\\"children\\":[]},{\\"name\\":\\"contact_count\\",\\"dataType\\":\\"BIGINT\\",\\"dataLength\\":1,\\"dataTypeDisplay\\":\\"bigint\\",\\"fullyQualifiedName\\":\\"financial_postgres.financial_db.analytics.customer_360.contact_count\\",\\"tags\\":[],\\"constraint\\":\\"NULL\\",\\"children\\":[]},{\\"name\\":\\"opportunity_count\\",\\"dataType\\":\\"BIGINT\\",\\"dataLength\\":1,\\"dataTypeDisplay\\":\\"bigint\\",\\"fullyQualifiedName\\":\\"financial_postgres.financial_db.analytics.customer_360.opportunity_count\\",\\"tags\\":[],\\"constraint\\":\\"NULL\\",\\"children\\":[]},{\\"name\\":\\"won_revenue\\",\\"dataType\\":\\"NUMERIC\\",\\"dataLength\\":1,\\"dataTypeDisplay\\":\\"numeric\\",\\"fullyQualifiedName\\":\\"financial_postgres.financial_db.analytics.customer_360.won_revenue\\",\\"tags\\":[],\\"constraint\\":\\"NULL\\",\\"children\\":[]},{\\"name\\":\\"support_case_count\\",\\"dataType\\":\\"BIGINT\\",\\"dataLength\\":1,\\"dataTypeDisplay\\":\\"bigint\\",\\"fullyQualifiedName\\":\\"financial_postgres.financial_db.analytics.customer_360.support_case_count\\",\\"tags\\":[],\\"constraint\\":\\"NULL\\",\\"children\\":[]},{\\"name\\":\\"last_activity_at\\",\\"dataType\\":\\"TIMESTAMP\\",\\"dataLength\\":1,\\"dataTypeDisplay\\":\\"timestamp with time zone\\",\\"fullyQualifiedName\\":\\"financial_postgres.financial_db.analytics.customer_360.last_activity_at\\",\\"tags\\":[],\\"constraint\\":\\"NULL\\",\\"children\\":[]}],\\"tableConstraints\\":[],\\"owners\\":[],\\"databaseSchema\\":{\\"id\\":\\"f3d8065c-9791-407a-8259-2927c6e46de1\\",\\"type\\":\\"databaseSchema\\",\\"name\\":\\"analytics\\",\\"fullyQualifiedName\\":\\"financial_postgres.financial_db.analytics\\",\\"displayName\\":\\"analytics\\",\\"deleted\\":false},\\"database\\":{\\"id\\":\\"57ba6ced-44ed-43c9-8173-a28f15aa629f\\",\\"type\\":\\"database\\",\\"name\\":\\"financial_db\\",\\"fullyQualifiedName\\":\\"financial_postgres.financial_db\\",\\"displayName\\":\\"financial_db\\",\\"deleted\\":false},\\"service\\":{\\"id\\":\\"41b71da5-e3c4-420c-8326-2f4fec2c6eb1\\",\\"type\\":\\"databaseService\\",\\"name\\":\\"financial_postgres\\",\\"fullyQualifiedName\\":\\"financial_postgres\\",\\"displayName\\":\\"financial_postgres\\",\\"deleted\\":false},\\"serviceType\\":\\"Postgres\\",\\"schemaDefinition\\":\\"create view analytics.customer_360 as  SELECT c.customer_id,\\\\n    c.customer_number,\\\\n    COALESCE(c.company_name, concat_ws(' '::text, c.first_name, c.last_name)::character varying) AS customer_name,\\\\n    c.customer_type,\\\\n    c.segment,\\\\n    c.industry,\\\\n    c.country,\\\\n    c.customer_status,\\\\n    count(DISTINCT ct.contact_id) AS contact_count,\\\\n    count(DISTINCT o.opportunity_id) AS opportunity_count,\\\\n    COALESCE(sum(DISTINCT o.amount) FILTER (WHERE o.sales_stage::text = 'Closed Won'::text), 0::numeric) AS won_revenue,\\\\n    count(DISTINCT sc.case_id) AS support_case_count,\\\\n    max(a.activity_at) AS last_activity_at\\\\n   FROM crm.customers c\\\\n     LEFT JOIN crm.contacts ct ON ct.customer_id = c.customer_id\\\\n     LEFT JOIN crm.opportunities o ON o.customer_id = c.customer_id\\\\n     LEFT JOIN crm.support_cases sc ON sc.customer_id = c.customer_id\\\\n     LEFT JOIN crm.activities a ON a.customer_id = c.customer_id\\\\n  GROUP BY c.customer_id;\\",\\"deleted\\":false,\\"domains\\":[],\\"sourceHash\\":\\"d254779960de0665655fe06dee19900f\\",\\"processedLineage\\":false,\\"entityStatus\\":\\"Unprocessed\\"}"}	1785560110900	ingestion-bot table financial_postgres.financial_db.analytics.customer_360 financial_postgres entitycreated
