.json\\"\\n    },\\n    \\"lifeCycle\\" : {\\n      \\"description\\" : \\"Life Cycle properties of the entity\\",\\n      \\"$ref\\" : \\"../../type/lifeCycle.json\\"\\n    },\\n    \\"certification\\" : {\\n      \\"$ref\\" : \\"../../type/assetCertification.json\\"\\n    },\\n    \\"sourceHash\\" : {\\n      \\"description\\" : \\"Source hash of the entity\\",\\n      \\"type\\" : \\"string\\",\\n      \\"minLength\\" : 1,\\n      \\"maxLength\\" : 32\\n    },\\n    \\"processedLineage\\" : {\\n      \\"description\\" : \\"Processed lineage for the stored procedure\\",\\n      \\"type\\" : \\"boolean\\",\\n      \\"default\\" : false\\n    },\\n    \\"entityStatus\\" : {\\n      \\"description\\" : \\"Status of the StoredProcedure.\\",\\n      \\"$ref\\" : \\"../../type/status.json\\"\\n    }\\n  },\\n  \\"required\\" : [ \\"id\\", \\"name\\", \\"storedProcedureCode\\" ],\\n  \\"additionalProperties\\" : false\\n}", "version": 0.1, "category": "entity", "nameSpace": "data", "updatedAt": 1785556669125, "updatedBy": "admin", "description": "\\"A `StoredProcedure` entity that contains the set of code statements with an assigned name  and is defined in a `Database Schema`.\\\\\\"\\"", "displayName": "storedProcedure", "dataProducts": [], "customProperties": [], "fullyQualifiedName": "storedProcedure"}
f6ceae19-9d27-4c49-b47b-20224e18b453	type.version.0.1	type	{"id": "f6ceae19-9d27-4c49-b47b-20224e18b453", "name": "spreadsheet", "schema": "{\\n  \\"$id\\" : \\"https://open-metadata.org/schema/entity/data/spreadsheet.json\\",\\n  \\"$schema\\" : \\"http://json-schema.org/draft-07/schema#\\",\\n  \\"title\\" : \\"Spreadsheet\\",\\n  \\"$comment\\" : \\"@om-entity-type\\",\\n  \\"description\\" : \\"This schema defines the Spreadsheet entity. A Spreadsheet is a file containing multiple worksheets/tabs, such as Google Sheets or Excel files.\\",\\n  \\"type\\" : \\"object\\",\\n  \\"javaType\\" : \\"org.openmetadata.schema.entity.data.Spreadsheet\\",\\n  \\"javaInterfaces\\" : [ \\"org.openmetadata.schema.EntityInterface\\" ],\\n  \\"definitions\\" : {\\n    \\"spreadsheetMimeType\\" : {\\n      \\"description\\" : \\"MIME type for spreadsheet files\\",\\n      \\"javaInterfaces\\" : [ \\"org.openmetadata.schema.EnumInterface\\" ],\\n      \\"type\\" : \\"string\\",\\n      \\"enum\\" : [ \\"application/vnd.google-apps.spreadsheet\\", \\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\\", \\"application/vnd.ms-excel\\", \\"application/vnd.oasis.opendocument.spreadsheet\\", \\"text/csv\\", \\"text/tab-separated-values\\", \\"Other\\" ],\\n      \\"javaEnums\\" : [ {\\n        \\"name\\" : \\"GoogleSheets\\"\\n      }, {\\n        \\"name\\" : \\"ExcelXlsx\\"\\n      }, {\\n        \\"name\\" : \\"ExcelXls\\"\\n      }, {\\n        \\"name\\" : \\"OpenDocument\\"\\n      }, {\\n        \\"name\\" : \\"Csv\\"\\n      }, {\\n        \\"name\\" : \\"Tsv\\"\\n      }, {\\n        \\"name\\" : \\"Other\\"\\n      } ]\\n    }\\n  },\\n  \\"properties\\" : {\\n    \\"id\\" : {\\n      \\"description\\" : \\"Unique identifier that identifies this spreadsheet instance.\\",\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/uuid\\"\\n    },\\n    \\"name\\" : {\\n      \\"description\\" : \\"Name that identifies the spreadsheet.\\",\\n      \\"$ref\\" : \