1.6.0	-- Data Insight charts: add metrics field\nUPDATE \n  di_chart_entity \nSET \n  json = jsonb_set(\n    json #- '{chartDetails,formula}' #- '{chartDetails,filter}' #- '{chartDetails,function}' #- '{chartDetails,field}' #- '{chartDetails,treeFilter}',\n    '{chartDetails,metrics}', \n    jsonb_build_array(\n      jsonb_strip_nulls(\n        jsonb_build_object(\n          'formula', json -> 'chartDetails' -> 'formula', \n          'filter', json -> 'chartDetails' -> 'filter', \n          'function', json -> 'chartDetails' -> 'function', \n          'field', json -> 'chartDetails' -> 'field', \n          'treeFilter', json -> 'chartDetails' -> 'treeFilter'\n        )\n      )\n    )\n  )\nWHERE \n  json -> 'chartDetails' -> 'metrics' is null	750d51ea3f51b5db7995f9d453c313b0	2026-08-01 03:49:50.682682
1.6.0	-- Rename and remove 'offset' to 'currentOffset' and add 'startingOffset'\nUPDATE change_event_consumers\nSET json = jsonb_set(\n                jsonb_set(\n                    json - 'offset',\n                    '{currentOffset}', json -> 'offset'\n                ),\n                '{startingOffset}', json -> 'offset'\n            )\nWHERE json -> 'offset' IS NOT NULL\n  AND jsonSchema = 'eventSubscriptionOffset'	87d0f4be2c106a51e673e3b232b2ca35	2026-08-01 03:49:50.70747
