1.11.8	-- Migrate Salesforce connection from sobjectName (string) to sobjectNames (array)\n-- Converts sobjectName to sobjectNames array and removes the old field\n\nUPDATE dbservice_entity\nSET json = jsonb_set(\n    json::jsonb #- '{connection,config,sobjectName}',\n    '{connection,config,sobjectNames}',\n    jsonb_build_array(json->'connection'->'config'->>'sobjectName')\n)::json\nWHERE serviceType = 'Salesforce'\n  AND json->'connection'->'config'->>'sobjectName' IS NOT NULL	094a5af71c358dbf2d78655d896c1059	2026-08-01 03:51:26.365294
1.11.11	-- Migrate REST API service connections: move flat openAPISchemaURL into nested openAPISchemaConnection object\nUPDATE api_service_entity\nSET json = jsonb_set(\n    json #- '{connection,config,openAPISchemaURL}',\n    '{connection,config,openAPISchemaConnection}',\n    jsonb_build_object('openAPISchemaURL', json #> '{connection,config,openAPISchemaURL}'),\n    true\n)\nWHERE serviceType = 'Rest'\n  AND jsonb_exists(json -> 'connection' -> 'config', 'openAPISchemaURL')\n  AND NOT jsonb_exists(json -> 'connection' -> 'config', 'openAPISchemaConnection')	e1c6996c11bdef4018f26821d443f819	2026-08-01 03:51:26.39844
1.11.12	-- Migrate Redshift connection: move password into authType.password (basicAuth)\nUPDATE dbservice_entity\nSET json = jsonb_set(\n    json #- '{connection,config,password}',\n    '{connection,config,authType}',\n    jsonb_build_object('password', json #> '{connection,config,password}')\n)\nWHERE serviceType = 'Redshift'\n  AND json #> '{connection,config,password}' IS NOT NULL\n  AND NOT jsonb_exists(json #> '{connection,config}', 'authType')	e738ff4e0603464578cf5757f2f052f8	2026-08-01 03:51:26.414989
1.11.12	-- Migrate OpenLineage connection config: move Kafka-specific fields into brokerConfig\n-- Supports the schema change adding Kinesis as an alternative broker type\nUPDATE pipeline_service_entity\nSET json = jsonb_set(\n    json,\n    '{connection,config,brokerConfig}',\n    (json #> '{connection,config}') - 'type' - 'pipelineFilterPattern' - 'supportsMetadataExtraction',\n    true\n)\n#- '{connection,config,brokersUrl}'\n#- '{connection,config,topicName}'\n#- '{connection,config,consumerGroupName}'\n#- '{connection,config,consumerOffsets}'\n#- '{connection,config,poolTimeout}'\n#- '{connection,config,sessionTimeout}'\n#- '{connection,config,securityProtocol}'\n#- '{connection,config,sslConfig}'\n#- '{connection,config,saslConfig}'\nWHERE serviceType = 'OpenLineage'\n  AND jsonb_exists(json #> '{connection,config}', 'brokersUrl')\n  AND NOT jsonb_exists(json #> '{connection,config}', 'brokerConfig')	84c531f1f4578b165bc6b173d4a893ad	2026-08-01 03:51:26.422675
