resourceType\\" : {\\n      \\"$ref\\" : \\"#/definitions/resourceType\\"\\n    },\\n    \\"categories\\" : {\\n      \\"description\\" : \\"Topic categories the resource belongs to.\\",\\n      \\"type\\" : \\"array\\",\\n      \\"items\\" : {\\n        \\"$ref\\" : \\"#/definitions/resourceCategory\\"\\n      },\\n      \\"minItems\\" : 1\\n    },\\n    \\"difficulty\\" : {\\n      \\"$ref\\" : \\"#/definitions/resourceDifficulty\\"\\n    },\\n    \\"source\\" : {\\n      \\"$ref\\" : \\"#/definitions/resourceSource\\"\\n    },\\n    \\"estimatedDuration\\" : {\\n      \\"description\\" : \\"Approximate viewing time in seconds.\\",\\n      \\"type\\" : \\"integer\\",\\n      \\"minimum\\" : 0\\n    },\\n    \\"contexts\\" : {\\n      \\"description\\" : \\"List of contexts where this resource should surface.\\",\\n      \\"type\\" : \\"array\\",\\n      \\"items\\" : {\\n        \\"$ref\\" : \\"#/definitions/resourceContext\\"\\n      },\\n      \\"minItems\\" : 1\\n    },\\n    \\"status\\" : {\\n      \\"description\\" : \\"Lifecycle state for controllable publishing.\\",\\n      \\"type\\" : \\"string\\",\\n      \\"enum\\" : [ \\"Draft\\", \\"Active\\", \\"Deprecated\\" ],\\n      \\"default\\" : \\"Active\\"\\n    },\\n    \\"tags\\" : {\\n      \\"description\\" : \\"Tags attached to the learning resource.\\",\\n      \\"type\\" : \\"array\\",\\n      \\"items\\" : {\\n        \\"$ref\\" : \\"../../type/tagLabel.json\\"\\n      },\\n      \\"default\\" : [ ]\\n    },\\n    \\"owners\\" : {\\n      \\"description\\" : \\"Owners accountable for maintaining this resource.\\",\\n      \\"$ref\\" : \\"../../type/entityReferenceList.json\\"\\n    },\\n    \\"reviewers\\" : {\\n      \\"$ref\\" : \\"../../type/entityReferenceList.json\\"\\n    },\\n    \\"followers\\" : {\\n      \\"$ref\\" : \\"../../type/entityReferenceList.json\\"\\n    },\\n    \\"changeDescription\\" : {\\n      \\"$ref\\" : \\"../../type/entityHistory.json#/definitions/changeDescription\\"\\n    },\\n    \\"incrementalChangeDescription\\" : {\\n      \\"$ref\\" : \\"../../type/entityHistory.json#/definitions/changeDescription\\"\\n    },\\n    \\"deleted\\" : {\\n      \\"description\\" : \\"Soft delete marker.\\",\\n      \\"type\\" : \\"boolean\\",\\n      \\"default\\" : false\\n    },\\n    \\"version\\" : {\\n      \\"$ref\\" : \\"../../type/entityHistory.json#/definitions/entityVersion\\"\\n    },\\n    \\"updatedAt\\" : {\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/timestamp\\"\\n    },\\n    \\"updatedBy\\" : {\\n      \\"type\\" : \\"string\\"\\n    },\\n    \\"impersonatedBy\\" : {\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/impersonatedBy\\"\\n    },\\n    \\"href\\" : {\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/href\\"\\n    },\\n    \\"extension\\" : {\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/entityExtension\\"\\n    }\\n  },\\n  \\"required\\" : [ \\"id\\", \\"name\\", \\"resourceType\\", \\"source\\", \\"contexts\\", \\"categories\\" ],\\n  \\"additionalProperties\\" : false\\n}", "version": 0.2, "category": "entity", "nameSpace": "learning", "updatedAt": 1785557015568, "updatedBy": "admin", "description": "&#34;A learning resource such as an in-product tutorial, Storylane walkthrough, or expert video contextualized for product surfaces.&#34;", "displayName": "learningResource", "changeDescription": {"fieldsAdded": [], "changeSummary": {"description": {"changedAt": 1785557015568, "changedBy": "admin"}}, "fieldsDeleted": [], "fieldsUpdated": [{"name": "description", "newValue": "&#34;A learning resource such as an in-product tutorial, Storylane walkthrough, or expert video contextualized for product surfaces.&#34;", "oldValue": "\\"A learning resource such as an in-product tutorial, Storylane walkthrough, or expert video contextualized for product surfaces.\\""}], "previousVersion": 0.1}, "fullyQualifiedName": "learningResource", "incrementalChangeDescription": {"fieldsAdded": [], "changeSummary": {"description": {"changedAt": 1785557015568, "changedBy": "admin", "changeSource": "Manual"}}, "fieldsDeleted": [], "fieldsUpdated": [{"name": "description", "newValue": "&#34;A learning resource such as an in-product tutorial, Storylane walkthrough, or expert video contextualized for product surfaces.&#34;", "oldValue": "\\"A learning resource such as an in-product tutorial, Storylane walkthrough, or expert video contextualized for product surfaces.\\""}], "previousVersion": 0.1}}	99b1bec11d70686d80f9cea0d5586111
{"id": "76008e4f-f0df-4306-b5b7-1cefd52590ec", "name": "classification", "schema": "{\\n  \\"$id\\" : \\"https://open-metadata.org/schema/entity/classification/classification.json\\",\\n  \\"$schema\\" : \\"http://json-schema.org/draft-07/schema#\\",\\n  \\"title\\" : \\"Classification\\",\\n  \\"$comment\\" : \\"@om-entity-type\\",\\n  \\"description\\" : \\"A `Classification` entity contains hierarchical terms called tags used for categorizing and classifying data assets and other entities.\\",\\n  \\"type\\" : \\"object\\",\\n  \\"javaType\\" : \\"org.openmetadata.schema.entity.classification.Classification\\",\\n  \\"javaInterfaces\\" : [ \\"org.openmetadata.schema.EntityInterface\\" ],\\n  \\"properties\\" : {\\n    \\"id\\" : {\\n      \\"description\\" : \\"Unique identifier of this entity instance.\\",\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/uuid\\"\\n    },\\n    \\"name\\" : {\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/entityName\\"\\n    },\\n    \\"fullyQualifiedName\\" : {\\n      \\"description\\" : \\"FullyQualifiedName same as `name`.\\",\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/fullyQualifiedEntityName\\"\\n    },\\n    \\"displayName\\" : {\\n      \\"description\\" : \\"Display Name that identifies this entity.\\",\\n      \\"type\\" : \\"string\\"\\n    },\\n    \\"description\\" : {\\n      \\"description\\" : \\"Description of the classification.\\",\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/markdown\\"\\n    },\\n    \\"version\\" : {\\n      \\"description\\" : \\"Metadata version of the entity.\\",\\n      \\"$ref\\" : \\"../../type/entityHistory.json#/definitions/entityVersion\\"\\n    },\\n    \\"termCount\\" : {\\n      \\"description\\" : \\"Total number of children tag terms under this classification. This includes all the children in the hierarchy.\\",\\n      \\"type\\" : \\"integer\\",\\n      \\"minimum\\" : 0\\n    },\\n    \\"updatedAt\\" : {\\n      \\"description\\" : \\"Last update time corresponding to the new version of the entity in Unix epoch time milliseconds.\\",\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/timestamp\\"\\n    },\\n    \\"updatedBy\\" : {\\n      \\"description\\" : \\"User who made the update.\\",\\n      \\"type\\" : \\"string\\"\\n    },\\n    \\"impersonatedBy\\" : {\\n      \\"description\\" : \\"Bot user that performed the action on behalf of the actual user.\\",\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/impersonatedBy\\"\\n    },\\n    \\"href\\" : {\\n      \\"description\\" : \\"Link to the resource corresponding to the classification.\\",\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/href\\"\\n    },\\n    \\"usageCount\\" : {\\n      \\"description\\" : \\"Count of how many times the tags from this classification are used.\\",\\n      \\"type\\" : \\"integer\\"\\n    },\\n    \\"changeDescription\\" : {\\n      \\"description\\" : \\"Change that lead to this version of the entity.\\",\\n      \\"$ref\\" : \\"../../type/entityHistory.json#/definitions/changeDescription\\"\\n    },\\n    \\"incrementalChangeDescription\\" : {\\n      \\"description\\" : \\"Change that lead to this version of the entity.\\",\\n      \\"$ref\\" : \\"../../type/entityHistory.json#/definitions/changeDescription\\"\\n    },\\n    \\"deleted\\" : {\\n      \\"description\\" : \\"When `true` indicates the entity has been soft deleted.\\",\\n      \\"type\\" : \\"boolean\\",\\n      \\"default\\" : false\\n    },\\n    \\"provider\\" : {\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/providerType\\"\\n    },\\n    \\"disabled\\" : {\\n      \\"description\\" : \\"System classifications can't be deleted. Use this flag to disable them.\\",\\n      \\"type\\" : \\"boolean\\",\\n      \\"default\\" : false\\n    },\\n    \\"mutuallyExclusive\\" : {\\n      \\"description\\" : \\"Tags under this classification are mutually exclusive. When mutually exclusive is `true` the tags from this classification are used to **classify** an entity. An entity can only be in one class - example, it can only be either `tier1` or `tier2` and not both. When mutually exclusive is `false`, the tags from this classification are used to **categorize** an entity. An entity have multiple tags simultaneously - example a customer can be `newCustomer` and `atRisk` simultaneously.\\",\\n      \\"type\\" : \\"boolean\\",\\n      \\"default\\" : \\"false\\"\\n    },\\n    \\"domains\\" : {\\n      \\"description\\" : \\"Domains the asset belongs to. When not set, the asset inherits the domain from the parent it belongs to.\\",\\n      \\"$ref\\" : \\"../../type/entityReferenceList.json\\"\\n    },\\n    \\"owners\\" : {\\n      \\"description\\" : \\"Owners of this Classification.\\",\\n      \\"$ref\\" : \\"../../type/entityReferenceList.json\\"\\n    },\\n    \\"reviewers\\" : {\\n      \\"description\\" : \\"User references of the reviewers for this tag.\\",\\n      \\"$ref\\" : \\"../../type/entityReferenceList.json\\"\\n    },\\n    \\"entityStatus\\" : {\\n      \\"description\\" : \\"Status of the tag.\\",\\n      \\"$ref\\" : \\"../../type/status.json\\"\\n    },\\n    \\"autoClassificationConfig\\" : {\\n      \\"description\\" : \\"Configuration for automatic classification behavior\\",\\n      \\"type\\" : \\"object\\",\\n      \\"properties\\" : {\\n        \\"enabled\\" : {\\n          \\"description\\" : \\"Whether automatic classification is enabled for this classification\\",\\n          \\"type\\" : \\"boolean\\",\\n          \\"default\\" : false\\n        },\\n        \\"conflictResolution\\" : {\\n          \\"description\\" : \\"Strategy for resolving conflicts when multiple tags match\\",\\n          \\"type\\" : \\"string\\",\\n          \\"enum\\" : [ \\"highest_confidence\\", \\"highest_priority\\", \\"most_specific\\" ],\\n          \\"default\\" : \\"highest_confidence\\"\\n        },\\n        \\"minimumConfidence\\" : {\\n          \\"description\\" : \\"Minimum confidence score required to apply a tag\\",\\n          \\"type\\" : \\"number\\",\\n          \\"minimum\\" : 0.0,\\n          \\"maximum\\" : 1.0,\\n          \\"default\\" : 0.6\\n        },\\n        \\"requireExplicitMatch\\" : {\\n          \\"description\\" : \\"Only apply tags when recognizers explicitly match (no default tagging)\\",\\n          \\"type\\" : \\"boolean\\",\\n          \\"default\\" : true\\n        }\\n      },\\n      \\"additionalProperties\\" : false\\n    }\\n  },\\n  \\"required\\" : [ \\"id\\", \\"name\\", \\"description\\" ],\\n  \\"additionalProperties\\" : false\\n}", "version": 0.2, "category": "entity", "nameSpace": "classification", "updatedAt": 1785557015617, "updatedBy": "admin", "description": "&#34;A &#96;Classification&#96; entity contains hierarchical terms called tags used for categorizing and classifying data assets and other entities.&#34;", "displayName": "classification", "changeDescription": {"fieldsAdded": [], "changeSummary": {"description": {"changedAt": 1785557015617, "changedBy": "admin"}}, "fieldsDeleted": [], "fieldsUpdated": [{"name": "description", "newValue": "&#34;A &#96;Classification&#96; entity contains hierarchical terms called tags used for categorizing and classifying data assets and other entities.&#34;", "oldValue": "\\"A `Classification` entity contains hierarchical terms called tags used for categorizing and classifying data assets and other entities.\\""}], "previousVersion": 0.1}, "fullyQualifiedName": "classification", "incrementalChangeDescription": {"fieldsAdded": [], "changeSummary": {"description": {"changedAt": 1785557015617, "changedBy": "admin", "changeSource": "Manual"}}, "fieldsDeleted": [], "fieldsUpdated": [{"name": "description", "newValue": "&#34;A &#96;Classification&#96; entity contains hierarchical terms called tags used for categorizing and classifying data assets and other entities.&#34;", "oldValue": "\\"A `Classification` entity contains hierarchical terms called tags used for categorizing and classifying data assets and other entities.\\""}], "previousVersion": 0.1}}	63f69c7f958795918b41fbcd71a8c811
{"id": "8fa4fa4d-b17b-42be-aa01-dd47b7bb4f69", "name": "tag", "schema": "{\\n  \\"$id\\" : \\"https://open-metadata.org/schema/entity/classification/tag.json\\",\\n  \\"$schema\\" : \\"http://json-schema.org/draft-07/schema#\\",\\n  \\"title\\" : \\"Tag\\",\\n  \\"$comment\\" : \\"@om-entity-type\\",\\n  \\"description\\" : \\"A `Tag` entity is used for classification or categorization. It is a term defined under `Classification` entity. Tags are used to label the entities and entity fields, such as Tables, and Columns.\\",\\n  \\"type\\" : \\"object\\",\\n  \\"javaType\\" : \\"org.openmetadata.schema.entity.classification.Tag\\",\\n  \\"javaInterfaces\\" : [ \\"org.openmetadata.schema.EntityInterface\\" ],\\n  \\"definitions\\" : { },\\n  \\"properties\\" : {\\n    \\"id\\" : {\\n      \\"description\\" : \\"Unique identifier of this entity instance.\\",\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/uuid\\"\\n    },\\n    \\"name\\" : {\\n      \\"description\\" : \\"Name of the tag.\\",\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/entityName\\"\\n    },\\n    \\"displayName\\" : {\\n      \\"description\\" : \\"Display Name that identifies this tag.\\",\\n      \\"type\\" : \\"string\\"\\n    },\\n    \\"fullyQualifiedName\\" : {\\n      \\"description\\" : \\"Unique name of the tag of format `Classification.tag1.tag2`.\\",\\n      \\"type\\" : \\"string\\"\\n    },\\n    \\"description\\" : {\\n      \\"description\\" : \\"Description of the tag.\\",\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/markdown\\"\\n    },\\n    \\"style\\" : {\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/style\\"\\n    },\\n    \\"classification\\" : {\\n      \\"description\\" : \\"Reference to the classification that this tag is part of.\\",\\n      \\"$ref\\" : \\"../../type/entityReference.json\\"\\n    },\\n    \\"parent\\" : {\\n      \\"description\\" : \\"Reference to the parent tag. When null, the term is at the root of the Classification.\\",\\n      \\"$ref\\" : \\"../../type/entityReference.json\\"\\n    },\\n    \\"children\\" : {\\n      \\"description\\" : \\"Children tags under this tag.\\",\\n      \\"$ref\\" : \\"../../type/entityReferenceList.json\\"\\n    },\\n    \\"version\\" : {\\n      \\"description\\" : \\"Metadata version of the entity.\\",\\n      \\"$ref\\" : \\"../../type/entityHistory.json#/definitions/entityVersion\\"\\n    },\\n    \\"updatedAt\\" : {\\n      \\"description\\" : \\"Last update time corresponding to the new version of the entity in Unix epoch time milliseconds.\\",\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/timestamp\\"\\n    },\\n    \\"updatedBy\\" : {\\n      \\"description\\" : \\"User who made the update.\\",\\n      \\"type\\" : \\"string\\"\\n    },\\n    \\"impersonatedBy\\" : {\\n      \\"description\\" : \\"Bot user that performed the action on behalf of the actual user.\\",\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/impersonatedBy\\"\\n    },\\n    \\"href\\" : {\\n      \\"description\\" : \\"Link to the resource corresponding to the tag.\\",\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/href\\"\\n    },\\n    \\"usageCount\\" : {\\n      \\"description\\" : \\"Count of how many times this tag and children tags are used.\\",\\n      \\"type\\" : \\"integer\\"\\n    },\\n    \\"deprecated\\" : {\\n      \\"description\\" : \\"If the tag is deprecated.\\",\\n      \\"type\\" : \\"boolean\\",\\n      \\"default\\" : false\\n    },\\n    \\"deleted\\" : {\\n      \\"description\\" : \\"When `true` indicates the entity has been soft deleted.\\",\\n      \\"type\\" : \\"boolean\\",\\n      \\"default\\" : false\\n    },\\n    \\"changeDescription\\" : {\\n      \\"description\\" : \\"Change that lead to this version of the entity.\\",\\n      \\"$ref\\" : \\"../../type/entityHistory.json#/definitions/changeDescription\\"\\n    },\\n    \\"incrementalChangeDescription\\" : {\\n      \\"description\\" : \\"Change that lead to this version of the entity.\\",\\n      \\"$ref\\" : \\"../../type/entityHistory.json#/definitions/changeDescription\\"\\n    },\\n    \\"provider\\" : {\\n      \\"$ref\\" : \\"../../type/basic.json#/definitions/providerType\\"\\n    },\\n    \\"disabled\\" : {\\n      \\"description\\" : \\"System tags can't be deleted. Use this flag to disable them.\\",\\n      \\"type\\" : \\"boolean\\",\\n      \\"default\\" : false\\n    },\\n    \\"mutuallyExclusive\\" : {\\n      \\"description\\" : \\"Children tags under this group are mutually exclusive. When mutually exclusive is `true` the tags from this group are used to **classify** an entity. An entity can only be in one class - example, it can only be either `tier1` or `tier2` and not both. When mutually exclusive is `false`, the tags from this group are used to **categorize** an entity. An entity can be in multiple categories simultaneously - example a customer can be `newCustomer` and `atRisk` simultaneously.\\",\\n      \\"type\\" : \\"boolean\\",\\n      \\"default\\" : \\"false\\"\\n    },\\n    \\"domains\\" : {\\n      \\"description\\" : \\"Domains the asset belongs to. When not set, the asset inherits the domain from the parent it belongs to.\\",\\n      \\"$ref\\" : \\"../../type/entityReferenceList.json\\"\\n    },\\n    \\"dataProducts\\" : {\\n      \\"description\\" : \\"List of data products this entity is part of.\\",\\n      \\"$ref\\" : \\"../../type/entityReferenceList.json\\"\\n    },\\n    \\"dataContract\\" : {\\n      \\"description\\" : \\"Reference to the data contract for this entity.\\",\\n      \\"$ref\\" : \\"../../type/entityReference.json\\"\\n    },\\n    \\"owners\\" : {\\n      \\"description\\" : \\"Owners of this glossary term.\\",\\n      \\"$ref\\" : \\"../../type/entityReferenceList.json\\"\\n    },\\n    \\"reviewers\\" : {\\n      \\"description\\" : \\"User references of the reviewers for this tag.\\",\\n      \\"$ref\\" : \\"../../type/entityReferenceList.json\\"\\n    },\\n    \\"entityStatus\\" : {\\n      \\"description\\" : \\"Status of the tag.\\",\\n      \\"$ref\\" : \\"../../type/status.json\\"\\n    },\\n    \\"recognizers\\" : {\\n      \\"description\\" : \\"List of recognizers configured for automatic detection of this tag\\",\\n      \\"type\\" : \\"array\\",\\n      \\"items\\" : {\\n        \\"$ref\\" : \\"../../type/recognizer.json\\"\\n      }\\n    },\\n    \\"autoClassificationEnabled\\" : {\\n      \\"description\\" : \\"Whether automatic classification is enabled for this tag\\",\\n      \\"type\\" : \\"boolean\\",\\n      \\"default\\" : false\\n    },\\n    \\"autoClassificationPriority\\" : {\\n      \\"description\\" : \\"Priority for conflict resolution when multiple tags match (higher number = higher priority)\\",\\n      \\"type\\" : \\"integer\\",\\n      \\"minimum\\" : 0,\\n      \\"maximum\\" : 100,\\n      \\"default\\" : 50\\n    }\\n  },\\n  \\"required\\" : [ \\"id\\", \\"name\\", \\"description\\" ],\\n  \\"additionalProperties\\" : false\\n}", "version": 0.2, "category": "entity", "nameSpace": "classification", "updatedAt": 1785557015739, "updatedBy": "admin", "description": "&#34;A &#96;Tag&#96; entity is used for classification or categorization. It is a term defined under &#96;Classification&#96; entity. Tags are used to label the entities and entity fields, such as Tables, and Columns.&#34;", "displayName": "tag", "changeDescription": {"fieldsAdded": [], "changeSummary": {"description": {"changedAt": 1785557015739, "changedBy": "admin"}}, "fieldsDeleted": [], "fieldsUpdated": [{"name": "description", "newValue": "&#34;A &#96;Tag&#96; entity is used for classification or categorization. It is a term defined under &#96;Classification&#96; entity. Tags are used to label the entities and entity fields, such as Tables, and Columns.&#34;", "oldValue": "\\"A `Tag` entity is used for classification or categorization. It is a term defined under `Classification` entity. Tags